const records = $input.all();

const lowKM = records
  .filter(record => {
    const km = record.json?.KM;
    return typeof km === 'number' && km <= 1000;
  })
  .map(record => ({
    json: {
      ...record.json,
      newUsed: "new"
    }
  }));

if (lowKM.length === 0) {
  return [{ json: { message: 'No records with 1000 KM or less', count: 0 } }];
}

return lowKM;

const records = $input.all();

const highKM = records
  .filter(record => {
    const km = record.json?.KM;
    return typeof km === 'number' && km >= 1001;
  })
  .map(record => ({
    json: {
      ...record.json,
      newUsed: "used"
    }
  }));

if (highKM.length === 0) {
  return [{ json: { message: 'No records with 1001 KM or more', count: 0 } }];
}

return highKM;

// ============================================================
// TRANSFORM: Flatten rows for Google Sheets
// ============================================================

const normalizeBodyType = (bodyType) => {
  if (!bodyType) return '';
  const b = bodyType.toString().toLowerCase().trim();
  if (b.includes('suv')) return 'SUV';
  if (b.includes('van')) return 'Van';
  if (b.includes('truck')) return 'Truck';
  if (b.includes('sedan') || b.includes('coupe')) return 'Sedan';
  return 'SUV';
};

const formatDest = (dest) => {
  if (dest === 'CAGE') return 'Cage slot';
  if (dest === 'FENCE') return 'Fence line';
  if (dest === 'LEFT SIDE' || dest === 'LEFT') return 'Left side';
  return dest || '';
};

// Get input data
const inputData = $input.first().json;
const rows = inputData.placementMap || [];

// If no rows, return debug info
if (rows.length === 0) {
  return [{
    json: {
      Zone: 'ERROR',
      Slot: 'NO_DATA',
      VIN: '',
      Year: '',
      Make: 'No placement data received',
      Model: '',
      Color: '',
      'Body Type': '',
      Category: '',
      Status: '',
      Assigned: '',
      Notes: ''
    }
  }];
}

return rows.map((row) => {
  let status = '';
  let notes = '';

  if (row.zone === 'LOOSE' && row.vin) {
    status = 'TEMP';
    notes = row.destinationZone ? `→ ${formatDest(row.destinationZone)}` : 'Awaiting space';
  } else if (row.vin) {
    // Use original Airtable INVENTORY STATUS
    status = row.status || '';
  }

  return {
    json: {
      Zone: row.zone || '',
      Slot: row.slot || '',
      VIN: row.vin || '',
      Year: row.year || '',
      Make: row.vin ? (row.make || '') : '',
      Model: row.model || '',
      Color: row.color || '',
      'Body Type': row.vin ? normalizeBodyType(row.bodyType) : '',
      Category: row.vin ? (row.category || '') : '',
      Status: status,
      Assigned: row.assigned || '',
      Notes: notes
    }
  };
});

// ============================================================
// BUILD TELEGRAM MESSAGE — LOT STATUS UPDATE
// ============================================================

const data = $('Run Placement Algorithm1').first().json;
const s = data.summary;
const looseAssignments = data.looseAssignments || [];
const excluded = data.excluded || [];

const ts = new Date().toLocaleString('en-US', { 
  timeZone: 'America/Edmonton', 
  hour12: true, 
  month: 'short', 
  day: 'numeric', 
  hour: 'numeric', 
  minute: '2-digit' 
});

// Helper to format destination zone
const formatDest = (dest) => {
  if (!dest) return 'UNKNOWN';
  const d = dest.toUpperCase();
  if (d === 'CAGE') return 'CAGED LOT';
  if (d === 'FENCE' || d === 'FENCE LINE') return 'FENCE - Right side of building';
  if (d === 'LEFT SIDE' || d === 'LEFT') return 'LEFT SIDE OF BUILDING';
  return dest.toUpperCase();
};

const totalOverflow = looseAssignments.length;

let msg = '';

// ── HEADER ──
msg += `<b>LOT STATUS</b> — ${ts}\n\n`;

// ── ZONE STATUS ──
msg += `<b>ZONE STATUS</b>\n`;
msg += `CAGED LOT:  ${s.cageFilled}/${s.cageCapacity} spots used\n`;
msg += `FENCE: ${s.fenceFilled}/${s.fenceCapacity} spots used\n`;
msg += `LEFT SIDE OF BUILDING:  ${s.leftFilled}/${s.leftCapacity} spots used\n\n`;

// ── SUMMARY ──
msg += `<b>-- SUMMARY --</b>\n`;
msg += `TOTAL OVERFLOW UNITS: ${totalOverflow}\n\n`;

// ── OVERFLOW LIST ──
if (totalOverflow > 0) {
  msg += `<b>-- OVERFLOW LIST --</b>\n\n`;

  for (const v of looseAssignments) {
    msg += `VIN: ${v.vin}\n`;
    msg += `${v.make} ${v.model} ${v.year} ${v.color || ''}\n`;
    msg += `parking spot: ${formatDest(v.destinationZone)}\n`;
    msg += `\n`;
  }
} else {
  msg += `✅ No overflow units. All vehicles have designated spots.\n\n`;
}

// ── DATA ISSUES ──
if (excluded.length > 0) {
  msg += `⚠️ ${excluded.length} vehicle(s) skipped — missing Airtable data\n\n`;
}

// ── REMINDERS ──
msg += `<b>Reminder:</b>\n`;
msg += `• When a unit arrives to location, please verify location in Airtable ASAP.\n`;
msg += `• When moving a unit to Sturgeon (Legal), please verify new location ASAP.\n`;

return [{ json: { text: msg } }];

const items = $input.all();

// --- Find the daily log entry (has "Date" and "Run Time") ---
const log = items.find(i => i.json['Date'] && i.json['Run Time'])?.json || {};

// --- Parse "17/20" format into filled/capacity ---
function parseFraction(str) {
  if (!str) return { filled: 0, capacity: 0 };
  const parts = String(str).split('/');
  return {
    filled: parseInt(parts[0]) || 0,
    capacity: parseInt(parts[1]) || 0
  };
}

const cage = parseFraction(log['Cage Filled']);
const fence = parseFraction(log['Fence Filled']);
const left = parseFraction(log['Left Filled']);

// --- Collect placement entries (have "Zone" and "Slot" but NOT "Date") ---
const placements = items
  .filter(i => i.json['Zone'] && i.json['Slot'] && !i.json['Date'] && !i.json['ok'])
  .map(i => {
    const d = i.json;
    return {
      zone: d['Zone'],
      slot: d['Slot'],
      vin: d['VIN'] || '',
      year: d['Year'] || '',
      make: d['Make'] || '',
      model: d['Model'] || '',
      color: d['Color'] || '',
      bodyType: (d['Body Type'] || '').toUpperCase(),
      category: d['Category'] || '',
      status: d['Status'] || '',
      notes: d['Notes'] || '',
      destinationZone: d['destinationZone'] || d['Destination Zone'] || ''
    };
  });

// --- Build escalations (LOOSE vehicles with a VIN) ---
const escalations = placements
  .filter(p => p.zone === 'LOOSE' && p.vin)
  .map(p => ({
    slot: p.slot,
    vin: p.vin,
    year: p.year,
    make: p.make,
    model: p.model,
    color: p.color,
    category: p.category,
    bodyType: p.bodyType,
    destinationZone: p.destinationZone
  }));

// --- Count by category ---
const byCategory = {};
placements.forEach(p => {
  if (p.vin && p.category) {
    byCategory[p.category] = (byCategory[p.category] || 0) + 1;
  }
});

const totalVehicles = parseInt(log['Vehicles Verified']) || placements.filter(p => p.vin).length;
const totalExcluded = parseInt(log['Excluded (Missing Data)']) || 0;

return [{
  json: {
    success: true,
    summary: {
      totalVehicles: totalVehicles,
      totalCategorized: totalVehicles - totalExcluded,
      totalExcluded: totalExcluded,
      totalPlaced: placements.filter(p => p.vin).length,
      cageFilled: cage.filled,
      cageCapacity: cage.capacity || 20,
      fenceFilled: fence.filled,
      fenceCapacity: fence.capacity || 5,
      leftFilled: left.filled,
      leftCapacity: left.capacity || 5,
      looseFilled: parseInt(log['Loose Used']) || escalations.length,
      looseCapacity: 'unlimited',
      stillUnplacedCount: 0,
      byCategory: byCategory
    },
    placementMap: placements,
    escalations: escalations,
    excluded: [],
    timestamp: new Date().toISOString()
  }
}];

// ============================================================
// PLACEMENT ALGORITHM — Assign vehicles to slots
// ============================================================

const input = $input.first().json;
const categorized = input.categorized || [];
const excluded = input.excluded || [];

// --- SLOT DEFINITIONS ---
const CAGE_SLOTS = ['C01','C02','C03','C04','C05','C06','C07','C08','C09','C10','C11','C12','C13','C14','C15','C16','C17','C18','C19','C20'];
const FENCE_SLOTS = ['F1','F2','F3','F4','F5'];
const LEFT_SLOTS = ['L1','L2','L3','L4','L5'];

// --- INITIALIZE PLACEMENT MAP ---
const placementMap = [];
const assignedVINs = new Set();

// Helper: Create empty slot entry
function emptySlot(zone, slot) {
  return {
    zone,
    slot,
    vin: '',
    year: '',
    make: '',
    model: '',
    color: '',
    bodyType: '',
    category: '',
    status: '',
    assigned: '',
    notes: '',
    destinationZone: ''
  };
}

// Helper: Create filled slot entry
function fillSlot(zone, slot, vehicle, notes = '', destZone = '') {
  assignedVINs.add(vehicle.vin);
  return {
    zone,
    slot,
    vin: vehicle.vin,
    year: vehicle.year,
    make: vehicle.make,
    model: vehicle.model,
    color: vehicle.color,
    bodyType: vehicle.bodyType,
    category: vehicle.category,
    status: vehicle.status,  // Original Airtable INVENTORY STATUS
    assigned: new Date().toISOString(),
    notes,
    destinationZone: destZone
  };
}

// Helper: Get available vehicles by category
function getByCategory(cat) {
  return categorized.filter(v => v.category === cat && !assignedVINs.has(v.vin));
}

// Helper: Sort vehicles by priority
function sortByPriority(vehicles) {
  return [...vehicles].sort((a, b) => {
    // Brand priority (lower = better)
    if (a.brandPriority !== b.brandPriority) return a.brandPriority - b.brandPriority;
    // Type priority (lower = better)
    if (a.typePriority !== b.typePriority) return a.typePriority - b.typePriority;
    // Year (newer = better)
    return b.year - a.year;
  });
}

// ============================================================
// PHASE 1: CAGE PLACEMENT
// ============================================================

// --- C01: NEW Compass/Wrangler only ---
let c01Vehicle = null;
const newVehicles = getByCategory('NEW');
const compassWrangler = newVehicles.filter(v => 
  v.model.toUpperCase().includes('COMPASS') || v.model.toUpperCase().includes('WRANGLER')
);
if (compassWrangler.length > 0) {
  const sorted = sortByPriority(compassWrangler);
  c01Vehicle = sorted[0];
  placementMap.push(fillSlot('CAGE', 'C01', c01Vehicle));
} else {
  placementMap.push(emptySlot('CAGE', 'C01')); // Allow empty per rules
}

// --- C02-C03: NEW SUVs, no Durango ---
const c02c03Slots = ['C02', 'C03'];
const newSUVsNoDurango = getByCategory('NEW').filter(v => 
  v.bodyType === 'SUV' && !v.model.toUpperCase().includes('DURANGO')
);
const sortedC02C03 = sortByPriority(newSUVsNoDurango);

for (let i = 0; i < c02c03Slots.length; i++) {
  if (sortedC02C03[i]) {
    placementMap.push(fillSlot('CAGE', c02c03Slots[i], sortedC02C03[i]));
  } else {
    // Fallback: VAN then TRUCK
    const fallback = getByCategory('NEW').filter(v => 
      v.bodyType === 'VAN' || v.bodyType === 'TRUCK'
    );
    const sortedFallback = sortByPriority(fallback);
    if (sortedFallback[0]) {
      placementMap.push(fillSlot('CAGE', c02c03Slots[i], sortedFallback[0]));
    } else {
      placementMap.push(emptySlot('CAGE', c02c03Slots[i]));
    }
  }
}

// --- C04-C07: NEW vehicles, full hierarchy ---
const c04c07Slots = ['C04', 'C05', 'C06', 'C07'];
const remainingNew = sortByPriority(getByCategory('NEW'));

for (let i = 0; i < c04c07Slots.length; i++) {
  if (remainingNew[i]) {
    placementMap.push(fillSlot('CAGE', c04c07Slots[i], remainingNew[i]));
  } else {
    placementMap.push(emptySlot('CAGE', c04c07Slots[i]));
  }
}

// --- C12-C13: Prefer trucks (NEW or FLR) ---
const c12c13Slots = ['C12', 'C13'];
const trucksForBack = sortByPriority([
  ...getByCategory('NEW').filter(v => v.bodyType === 'TRUCK'),
  ...getByCategory('FLR').filter(v => v.bodyType === 'TRUCK')
]);

for (let i = 0; i < c12c13Slots.length; i++) {
  if (trucksForBack[i]) {
    placementMap.push(fillSlot('CAGE', c12c13Slots[i], trucksForBack[i]));
  } else {
    // Fallback to any NEW/FLR
    const fallback = sortByPriority([...getByCategory('NEW'), ...getByCategory('FLR')]);
    if (fallback[0]) {
      placementMap.push(fillSlot('CAGE', c12c13Slots[i], fallback[0]));
    } else {
      placementMap.push(emptySlot('CAGE', c12c13Slots[i]));
    }
  }
}

// --- C08-C11, C14-C20: Remaining FLR/NEW ---
const remainderSlots = ['C08', 'C09', 'C10', 'C11', 'C14', 'C15', 'C16', 'C17', 'C18', 'C19', 'C20'];
const remainderVehicles = sortByPriority([
  ...getByCategory('NEW'),
  ...getByCategory('FLR')
]);

let remainderIdx = 0;
for (const slot of remainderSlots) {
  if (remainderVehicles[remainderIdx]) {
    placementMap.push(fillSlot('CAGE', slot, remainderVehicles[remainderIdx]));
    remainderIdx++;
  } else {
    placementMap.push(emptySlot('CAGE', slot));
  }
}

// Track overflow from cage (FLR that didn't fit)
const cageOverflow = sortByPriority([...getByCategory('NEW'), ...getByCategory('FLR')]);

// ============================================================
// PHASE 2: FENCE PLACEMENT (SOLD > BND > FLR Sedan overflow)
// ============================================================

const soldVehicles = sortByPriority(getByCategory('SOLD'));
const bndVehicles = sortByPriority(getByCategory('BND'));
const sedanOverflow = cageOverflow.filter(v => v.isSedan);

let fenceIdx = 0;

// Fill SOLD first
for (const v of soldVehicles) {
  if (fenceIdx < FENCE_SLOTS.length) {
    placementMap.push(fillSlot('FENCE', FENCE_SLOTS[fenceIdx], v));
    fenceIdx++;
  }
}

// Then BND
for (const v of bndVehicles) {
  if (fenceIdx < FENCE_SLOTS.length) {
    placementMap.push(fillSlot('FENCE', FENCE_SLOTS[fenceIdx], v));
    fenceIdx++;
  }
}

// Then sedan overflow from cage
for (const v of sedanOverflow) {
  if (fenceIdx < FENCE_SLOTS.length) {
    placementMap.push(fillSlot('FENCE', FENCE_SLOTS[fenceIdx], v));
    fenceIdx++;
  }
}

// Fill remaining fence slots as empty
while (fenceIdx < FENCE_SLOTS.length) {
  placementMap.push(emptySlot('FENCE', FENCE_SLOTS[fenceIdx]));
  fenceIdx++;
}

// Track fence overflow
const fenceOverflowSold = getByCategory('SOLD');
const fenceOverflowBND = getByCategory('BND');

// ============================================================
// PHASE 3: LEFT SIDE (BND overflow > RECON > SOLD overflow)
// ============================================================

const reconVehicles = sortByPriority(getByCategory('RECON'));

let leftIdx = 0;

// BND overflow first
for (const v of fenceOverflowBND) {
  if (leftIdx < LEFT_SLOTS.length) {
    placementMap.push(fillSlot('LEFT', LEFT_SLOTS[leftIdx], v));
    leftIdx++;
  }
}

// Then RECON
for (const v of reconVehicles) {
  if (leftIdx < LEFT_SLOTS.length) {
    placementMap.push(fillSlot('LEFT', LEFT_SLOTS[leftIdx], v));
    leftIdx++;
  }
}

// Then SOLD overflow
for (const v of fenceOverflowSold) {
  if (leftIdx < LEFT_SLOTS.length) {
    placementMap.push(fillSlot('LEFT', LEFT_SLOTS[leftIdx], v));
    leftIdx++;
  }
}

// Fill remaining left slots as empty
while (leftIdx < LEFT_SLOTS.length) {
  placementMap.push(emptySlot('LEFT', LEFT_SLOTS[leftIdx]));
  leftIdx++;
}

// ============================================================
// PHASE 4: LOOSE PARKING (everything that didn't fit)
// ============================================================

const looseAssignments = [];
let looseIdx = 1;

// All remaining unassigned vehicles go to loose parking
const allRemaining = categorized.filter(v => !assignedVINs.has(v.vin));

for (const v of allRemaining) {
  // Determine where this vehicle SHOULD go
  let destZone = 'CAGE';
  if (v.category === 'SOLD') destZone = 'FENCE';
  if (v.category === 'BND') destZone = 'FENCE';
  if (v.category === 'RECON') destZone = 'LEFT SIDE';

  const looseEntry = fillSlot('LOOSE', `LP${looseIdx}`, v, `Belongs in ${destZone}`, destZone);
  looseEntry.status = 'TEMPORARY';
  placementMap.push(looseEntry);
  looseAssignments.push({
    slot: `LP${looseIdx}`,
    vin: v.vin,
    year: v.year,
    make: v.make,
    model: v.model,
    color: v.color,
    category: v.category,
    bodyType: v.bodyType,
    destinationZone: destZone
  });
  looseIdx++;
}

// ============================================================
// BUILD SUMMARY
// ============================================================

const cageFilled = placementMap.filter(p => p.zone === 'CAGE' && p.vin).length;
const fenceFilled = placementMap.filter(p => p.zone === 'FENCE' && p.vin).length;
const leftFilled = placementMap.filter(p => p.zone === 'LEFT' && p.vin).length;
const looseFilled = placementMap.filter(p => p.zone === 'LOOSE').length;

const summary = {
  totalVehicles: categorized.length,
  totalPlaced: assignedVINs.size,
  cageFilled,
  cageCapacity: 20,
  fenceFilled,
  fenceCapacity: 5,
  leftFilled,
  leftCapacity: 5,
  looseFilled,
  looseCapacity: 'unlimited',
  byCategory: input.counts?.byCategory || {}
};

return [{
  json: {
    placementMap,
    summary,
    escalations: looseAssignments,
    excluded
  }
}];

// ============================================================
// GENERIC RULE ENGINE PARSER
// Phase 1: Load and structure the schema
// Phase 2: Parse and validate rules against schema
// Phase 3: Compile into structured config for downstream nodes
// ============================================================

const schemaRows = $('Read Schema1').all().map(i => i.json);
const rulesRows = $('Read Rules1').all().map(i => i.json);

// ============================================================
// PHASE 1: BUILD SCHEMA REGISTRY
// ============================================================

function buildSchema(rows) {
  const schema = {};

  for (const row of rows) {
    const ruleType = (row['Rule_Type'] || '').toString().trim().toUpperCase();
    const param = (row['Parameter'] || '').toString().trim().toLowerCase();
    const position = parseInt(row['Param_Position']) || 1;
    const dataType = (row['Data_Type'] || 'string').toString().trim().toLowerCase();
    const required = (row['Required'] || '').toString().toUpperCase() === 'TRUE';
    const validValues = row['Valid_Values'] 
      ? row['Valid_Values'].toString().split(',').map(v => v.trim().toUpperCase())
      : null;
    const defaultVal = row['Default'] !== undefined && row['Default'] !== '' 
      ? row['Default'].toString() 
      : null;
    const description = (row['Description'] || '').toString();

    if (!ruleType || !param) continue;

    if (!schema[ruleType]) {
      schema[ruleType] = { params: {}, paramOrder: [] };
    }

    schema[ruleType].params[param] = {
      position,
      dataType,
      required,
      validValues,
      default: defaultVal,
      description
    };

    schema[ruleType].paramOrder.push({ name: param, position });
  }

  // Sort params by position for each rule type
  for (const ruleType in schema) {
    schema[ruleType].paramOrder.sort((a, b) => a.position - b.position);
  }

  return schema;
}

// ============================================================
// PHASE 2: PARSE AND VALIDATE RULES
// ============================================================

function parseValue(value, dataType) {
  const v = (value !== undefined && value !== null) ? value.toString().trim() : '';

  switch (dataType) {
    case 'integer':
      const intVal = parseInt(v);
      return isNaN(intVal) ? null : intVal;
    case 'boolean':
      return v.toUpperCase() === 'TRUE';
    case 'enum':
    case 'string':
    case 'field_name':
    case 'slot_range':
    case 'any':
    default:
      return v;
  }
}

function validateAndParseRules(rows, schema) {
  const parsed = [];
  const errors = [];
  const warnings = [];

  for (const row of rows) {
    const ruleId = (row['Rule_ID'] || '').toString().trim();
    const ruleType = (row['Rule_Type'] || '').toString().trim().toUpperCase();
    const enabled = (row['Enabled'] || '').toString().toUpperCase();
    const notes = (row['Notes'] || '').toString().trim();

    // Skip disabled rules
    if (enabled !== 'TRUE' && enabled !== true) {
      continue;
    }

    // Skip empty rows
    if (!ruleId || !ruleType) {
      continue;
    }

    // Validate rule type exists in schema
    if (!schema[ruleType]) {
      errors.push({
        ruleId,
        error: `Unknown rule type: ${ruleType}`,
        suggestion: `Valid types: ${Object.keys(schema).join(', ')}`
      });
      continue;
    }

    const ruleSchema = schema[ruleType];
    const params = {};
    const ruleErrors = [];

    // Extract parameters from Param_1 through Param_5 based on schema position
    for (const paramDef of ruleSchema.paramOrder) {
      const paramName = paramDef.name;
      const paramConfig = ruleSchema.params[paramName];
      const colName = `Param_${paramConfig.position}`;
      const rawValue = row[colName];

      // Check required
      if (paramConfig.required && (rawValue === undefined || rawValue === null || rawValue === '')) {
        if (paramConfig.default !== null) {
          params[paramName] = parseValue(paramConfig.default, paramConfig.dataType);
        } else {
          ruleErrors.push(`Missing required parameter: ${paramName} (${colName})`);
        }
        continue;
      }

      // Parse value
      const parsedValue = parseValue(rawValue, paramConfig.dataType);

      // Validate against valid_values if defined (for enum types)
      if (paramConfig.validValues && parsedValue !== '' && parsedValue !== null) {
        const upperValue = parsedValue.toString().toUpperCase();
        // For comma-separated values, check each one
        const valuesToCheck = upperValue.includes(',') 
          ? upperValue.split(',').map(v => v.trim())
          : [upperValue];

        for (const v of valuesToCheck) {
          if (v && !paramConfig.validValues.includes(v) && !paramConfig.validValues.includes('*')) {
            warnings.push({
              ruleId,
              warning: `Value '${v}' for ${paramName} not in valid_values list`,
              validValues: paramConfig.validValues
            });
          }
        }
      }

      params[paramName] = parsedValue;
    }

    if (ruleErrors.length > 0) {
      errors.push({ ruleId, ruleType, errors: ruleErrors });
      continue;
    }

    parsed.push({
      id: ruleId,
      type: ruleType,
      params,
      notes,
      _raw: row
    });
  }

  return { parsed, errors, warnings };
}

// ============================================================
// PHASE 3: COMPILE INTO STRUCTURED CONFIG
// ============================================================

function compileRules(parsedRules) {
  const compiled = {
    // Legacy format (for backward compatibility)
    general: {},
    statusMap: {},
    statusOverrides: [],
    brandPriority: {},
    defaultBrandPriority: 5,
    bodyTypeMap: {},
    bodyTypePriority: {},
    cageSlotRules: [],
    fenceRules: [],
    leftRules: [],
    overflowRules: {},

    // New structured format
    categoryAssign: [],
    categoryOverride: [],
    slotConstraints: [],
    zonePriority: { FENCE: [], LEFT: [] },
    sortRules: [],
    valueMaps: {}
  };

  for (const rule of parsedRules) {
    const p = rule.params;

    switch (rule.type) {
      // --------------------------------------------------------
      // GENERAL SETTINGS
      // --------------------------------------------------------
      case 'GENERAL_SETTING':
        const settingName = p.setting_name;
        let settingValue = p.value;

        // Parse based on data_type hint
        if (p.data_type === 'integer') {
          settingValue = parseInt(settingValue) || 0;
        } else if (p.data_type === 'boolean') {
          settingValue = settingValue.toString().toUpperCase() === 'TRUE';
        }

        compiled.general[settingName] = settingValue;
        break;

      // --------------------------------------------------------
      // CATEGORY ASSIGNMENT
      // --------------------------------------------------------
      case 'CATEGORY_ASSIGN':
        const catRule = {
          id: rule.id,
          sourceField: p.source_field,
          operator: p.operator,
          threshold: p.threshold,
          outputCategory: p.output_category.toUpperCase(),
          priority: parseInt(p.priority) || 100
        };
        compiled.categoryAssign.push(catRule);

        // Also populate legacy statusMap for backward compatibility
        if (p.source_field === 'STATUS' && p.operator === '=') {
          compiled.statusMap[p.threshold.toUpperCase()] = p.output_category.toUpperCase();
        }
        break;

      // --------------------------------------------------------
      // CATEGORY OVERRIDE
      // --------------------------------------------------------
      case 'CATEGORY_OVERRIDE':
        const overrideRule = {
          id: rule.id,
          fromCategory: p.from_category.toUpperCase(),
          whenStatus: p.when_status.toUpperCase(),
          toCategory: p.to_category.toUpperCase(),
          priority: parseInt(p.priority) || 100
        };
        compiled.categoryOverride.push(overrideRule);
        compiled.statusOverrides.push(overrideRule); // Legacy alias
        break;

      // --------------------------------------------------------
      // VALUE MAPS
      // --------------------------------------------------------
      case 'VALUE_MAP':
        const mapName = p.map_name.toUpperCase();
        const inputVal = p.input_value.toUpperCase();
        const outputVal = p.output_value;

        if (!compiled.valueMaps[mapName]) {
          compiled.valueMaps[mapName] = {};
        }
        compiled.valueMaps[mapName][inputVal] = outputVal;

        // Populate legacy structures for backward compatibility
        switch (mapName) {
          case 'BRAND_PRIORITY':
            if (inputVal === '*') {
              compiled.defaultBrandPriority = parseInt(outputVal) || 5;
            } else {
              compiled.brandPriority[inputVal] = parseInt(outputVal) || 5;
            }
            break;
          case 'BODY_TYPE_NORM':
            compiled.bodyTypeMap[inputVal] = outputVal.toUpperCase();
            break;
          case 'BODY_TYPE_PRIORITY':
            compiled.bodyTypePriority[inputVal] = parseInt(outputVal) || 5;
            break;
        }
        break;

      // --------------------------------------------------------
      // SLOT CONSTRAINTS
      // --------------------------------------------------------
      case 'SLOT_CONSTRAINT':
        const slotRule = {
          id: rule.id,
          slots: p.slots,
          constraintType: p.constraint_type.toUpperCase(),
          value: p.value,
          priority: parseInt(p.priority) || 100
        };
        compiled.slotConstraints.push(slotRule);

        // Also populate legacy cageSlotRules
        compiled.cageSlotRules.push({
          slots: p.slots,
          ruleType: p.constraint_type.toUpperCase(),
          ruleValue: p.value
        });
        break;

      // --------------------------------------------------------
      // ZONE PRIORITY
      // --------------------------------------------------------
      case 'ZONE_PRIORITY':
        const zone = p.zone.toUpperCase();
        const zonePriorityRule = {
          id: rule.id,
          fillOrder: parseInt(p.fill_order) || 99,
          category: p.category.toUpperCase(),
          notes: p.notes || ''
        };

        if (zone === 'FENCE') {
          compiled.zonePriority.FENCE.push(zonePriorityRule);
          compiled.fenceRules.push({ priority: zonePriorityRule.fillOrder, category: zonePriorityRule.category });
        } else if (zone === 'LEFT') {
          compiled.zonePriority.LEFT.push(zonePriorityRule);
          compiled.leftRules.push({ priority: zonePriorityRule.fillOrder, category: zonePriorityRule.category });
        }
        break;

      // --------------------------------------------------------
      // SORT RULES
      // --------------------------------------------------------
      case 'SORT_RULE':
        compiled.sortRules.push({
          id: rule.id,
          field: p.field.toUpperCase(),
          direction: p.direction.toUpperCase(),
          order: parseInt(p.sort_order) || 99,
          notes: p.notes || ''
        });
        break;

      // --------------------------------------------------------
      // OVERFLOW RULES
      // --------------------------------------------------------
      case 'OVERFLOW_RULE':
        let ovfValue = p.value;
        if (ovfValue.toUpperCase() === 'TRUE') ovfValue = true;
        else if (ovfValue.toUpperCase() === 'FALSE') ovfValue = false;
        compiled.overflowRules[p.rule_name] = ovfValue;
        break;
    }
  }

  // Sort arrays that need ordering
  compiled.categoryAssign.sort((a, b) => a.priority - b.priority);
  compiled.categoryOverride.sort((a, b) => a.priority - b.priority);
  compiled.statusOverrides.sort((a, b) => a.priority - b.priority);
  compiled.slotConstraints.sort((a, b) => a.priority - b.priority);
  compiled.sortRules.sort((a, b) => a.order - b.order);
  compiled.zonePriority.FENCE.sort((a, b) => a.fillOrder - b.fillOrder);
  compiled.zonePriority.LEFT.sort((a, b) => a.fillOrder - b.fillOrder);
  compiled.fenceRules.sort((a, b) => a.priority - b.priority);
  compiled.leftRules.sort((a, b) => a.priority - b.priority);

  return compiled;
}

