  }
  if (rules.valueMaps.BODY_TYPE_PRIORITY) {
    Object.assign(bodyTypePriority, rules.valueMaps.BODY_TYPE_PRIORITY);
  }
}

const defaultBrandPriority = parseInt(brandPriority['*']) || 99;
const defaultBodyTypePriority = 99;

// --- GENERAL SETTINGS ---
const newKmThreshold = parseInt(rules.general?.NEW_KM_THRESHOLD) || 1000;

// --- CATEGORY ASSIGNMENT RULES ---
const categoryAssignRules = (rules.categoryAssign || []).sort((a, b) => (a.priority || 99) - (b.priority || 99));

// --- CATEGORY OVERRIDES ---
// --- CATEGORY OVERRIDES ---
const categoryOverrides = rules.categoryOverride || [
  { fromCategory: 'NEW', whenStatus: 'BOOKED | NOT DELIVERED', toCategory: 'BND' },
  { fromCategory: 'NEW', whenStatus: 'SIGNED DEAL', toCategory: 'SOLD' },
  { fromCategory: 'NEW', whenStatus: 'IN RECON', toCategory: 'RECON' },
  { fromCategory: 'NEW', whenStatus: 'VOID | IN STOCK', toCategory: 'FLR' }
];

// --- HELPER: Evaluate condition ---
function evaluateCondition(vehicle, rule) {
  // FIXED: Use correct field names from rule structure
  const field = (rule.sourceField || rule.field || '').toUpperCase();
  const operator = rule.operator || '=';
  const value = rule.threshold || rule.value || '';

  let vehicleValue;
  switch (field) {
    case 'KM': vehicleValue = parseInt(vehicle.km) || 0; break;
    case 'STATUS': vehicleValue = vehicle.inventoryStatus?.toUpperCase() || ''; break;
    case 'MAKE': vehicleValue = vehicle.make?.toUpperCase() || ''; break;
    case 'MODEL': vehicleValue = vehicle.model?.toUpperCase() || ''; break;
    case 'YEAR': vehicleValue = parseInt(vehicle.year) || 0; break;
    case 'TYPE': vehicleValue = vehicle.bodyType?.toUpperCase() || ''; break;
    default: return false;
  }

  // Numeric comparisons
  if (field === 'KM' || field === 'YEAR') {
    const numValue = parseFloat(value);
    switch (operator) {
      case '<=': return vehicleValue <= numValue;
      case '>=': return vehicleValue >= numValue;
      case '<': return vehicleValue < numValue;
      case '>': return vehicleValue > numValue;
      case '=': return vehicleValue === numValue;
      case '!=': return vehicleValue !== numValue;
    }
  }

  // String comparisons
  const compareValue = String(value).toUpperCase();
  switch (operator) {
    case '=': return vehicleValue === compareValue;
    case '!=': return vehicleValue !== compareValue;
    case 'IN': return compareValue.split(',').map(s => s.trim()).includes(vehicleValue);
    case 'NOT_IN': return !compareValue.split(',').map(s => s.trim()).includes(vehicleValue);
    default: return vehicleValue === compareValue;
  }
}

// --- HELPER: Assign category based on rules ---
function assignCategory(vehicle) {
  for (const rule of categoryAssignRules) {
    if (evaluateCondition(vehicle, rule)) {
      // FIXED: Use correct field name
      return rule.outputCategory || rule.category;
    }
  }
  return null;
}

// --- HELPER: Apply overrides ---
function applyOverrides(category, vehicle) {
  for (const override of categoryOverrides) {
    if (category === override.fromCategory) {
      const statusMatch = vehicle.inventoryStatus?.toUpperCase() === override.whenStatus?.toUpperCase();
      if (statusMatch) {
        return override.toCategory;
      }
    }
  }
  return category;
}

// --- PROCESS VEHICLES ---
const categorized = [];
const excluded = [];

for (const raw of vehiclesRaw) {
  const vin = raw['V.I.N.'] || raw.VIN || raw.vin || '';
  const make = raw.MAKE || raw.make || '';
  const model = raw.MODEL || raw.model || '';
  const year = parseInt(raw.YEAR || raw.year) || 0;
  const color = raw.COLOUR || raw.COLOR || raw.colour || raw.color || '';
  const km = parseInt(raw.KM || raw.km) || 0;
  const rawType = (raw.TYPE || raw.type || '').toUpperCase();
  const inventoryStatus = raw['INVENTORY STATUS'] || raw.INVENTORY_STATUS || '';

  // Validate required fields
  if (!vin || !make || !model) {
    excluded.push({ vin: vin || 'UNKNOWN', reason: 'Missing required fields (VIN, make, or model)', raw });
    continue;
  }

  // Normalize body type
  let bodyType = rawType;
  if (bodyTypeNorm[rawType]) {
    bodyType = typeof bodyTypeNorm[rawType] === 'object' 
      ? bodyTypeNorm[rawType].output || rawType 
      : bodyTypeNorm[rawType];
  }
  bodyType = bodyType || 'UNKNOWN';

  // Get brand priority
  let bPriority = brandPriority[make.toUpperCase()];
  if (bPriority === undefined) bPriority = defaultBrandPriority;
  bPriority = parseInt(bPriority) || defaultBrandPriority;

  // Get type priority
  let tPriority = bodyTypePriority[bodyType];
  if (tPriority === undefined) tPriority = defaultBodyTypePriority;
  tPriority = parseInt(tPriority) || defaultBodyTypePriority;

  // Build vehicle object for rule evaluation
  const vehicle = {
    vin,
    make,
    model,
    year,
    color,
    km,
    bodyType,
    inventoryStatus,
    isTruck: bodyType === 'TRUCK',
    isSedan: bodyType === 'SEDAN',
    brandPriority: bPriority,
    typePriority: tPriority
  };

  // Assign category using rules
  let category = assignCategory(vehicle);

  if (!category) {
    excluded.push({ vin, reason: 'No matching category rule', vehicle });
    continue;
  }

  // Apply overrides (e.g., NEW + BND status → BND)
  category = applyOverrides(category, vehicle);

  // Final categorized vehicle
  categorized.push({
    vin,
    make,
    model,
    year,
    color,
    km,
    bodyType,
    category,
    status: inventoryStatus,  // Direct passthrough from Airtable
    brandPriority: vehicle.brandPriority,
    typePriority: vehicle.typePriority,
    isTruck: vehicle.isTruck,
    isSedan: vehicle.isSedan
  });
}

// --- COUNT BY CATEGORY ---
const byCategory = {};
for (const v of categorized) {
  byCategory[v.category] = (byCategory[v.category] || 0) + 1;
}

return [{
  json: {
    categorized,
    excluded,
    counts: {
      total: vehiclesRaw.length,
      categorized: categorized.length,
      excluded: excluded.length,
      byCategory
    }
  }
}];

